import sys

def compute_lps(pattern):
    n = len(pattern)
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def main():
    s = sys.stdin.read().strip()
    if not s:
        return
    rev_s = s[::-1]
    combined = s + "#" + rev_s
    lps = compute_lps(combined)
    longest_pal_prefix_len = lps[-1]
    result = len(s) - longest_pal_prefix_len
    print(result)

if __name__ == "__main__":
    main()
